.set noat
.set noreorder

/* Auto-generated stub table.
   These are function pointer cells that the original game's boot
   patcher would fill at runtime. Since we link directly against the
   PsyQ libraries, we provide the real addresses immediately. */

/* Text stubs: jump trampolines to PsyQ library functions */
.macro  stub  name, target
.globl  \name
\name:
    j    \target
    nop
.endm

/* Data stubs: zero-initialized global variables */
.macro  datastub  name
.globl  \name
\name:
.word   0
.endm

/* Function-pointer stubs: alias the PsyQ library function directly */
.macro  textstub  name, target
.globl  \name
\name = \target
.endm

.section .text, "ax"

/* libc function trampolines */
stub  atoi,       atoi
stub  itoa,       itoa
stub  memcpy,     memcpy
stub  strcat,     strcat
stub  strcpy,     strcpy
stub  strlen,     strlen
stub  strstr,     strstr

/* PsyQ function aliases (game calls these by name; resolve to PsyQ lib) */
textstub  ApplyMatrixLV,   ApplyMatrix
textstub  ApplyMatrixSV,   ApplyMatrix

.section .data, "aw"

